<?php require_once '../config.php';require_admin();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){header('Location: index.php');exit;}$s=$pdo->prepare('SELECT * FROM Users WHERE admin_id=?');$s->execute([$id]);$u=$s->fetch();if(!$u){header('Location: index.php');exit;}$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$img=$u['images'];try{if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Email không hợp lệ.');if($pass!==''&&strlen($pass)<6)throw new RuntimeException('Mật khẩu tối thiểu 6 ký tự.');if(!empty($_FILES['image']['name'])){$f=$_FILES['image'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>3145728)throw new RuntimeException('Ảnh lỗi hoặc vượt quá 3MB.');$m=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$t=['image/jpeg'=>'jpg','image/png'=>'png','image/gif'=>'gif','image/webp'=>'webp'];if(!isset($t[$m]))throw new RuntimeException('Định dạng ảnh không hợp lệ.');$img=bin2hex(random_bytes(12)).'.'.$t[$m];if(!move_uploaded_file($f['tmp_name'],__DIR__.'/../uploads/'.$img))throw new RuntimeException('Không lưu được ảnh.');}
if($pass!==''){$s=$pdo->prepare('UPDATE Users SET admin_email=?,admin_password=?,images=? WHERE admin_id=?');$s->execute([$email,password_hash($pass,PASSWORD_DEFAULT),$img,$id]);}else{$s=$pdo->prepare('UPDATE Users SET admin_email=?,images=? WHERE admin_id=?');$s->execute([$email,$img,$id]);}$_SESSION['flash']='Đã cập nhật người dùng.';header('Location: index.php');exit;}catch(Throwable $e){$err=$e instanceof PDOException?'Email đã tồn tại.':$e->getMessage();}}
?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sửa user</title><link rel="stylesheet" href="../assets/style.css"></head><body><main class="formpage"><a href="index.php">← Quay lại</a><section class="panel"><small>ADMIN / USERS</small><h1>Sửa người dùng #<?=(int)$id?></h1><?php if($err):?><div class="alert"><?=e($err)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><label>Email</label><input type="email" name="email" required value="<?=e($_POST['email']??$u['admin_email'])?>"><label>Mật khẩu mới</label><input type="password" name="password" minlength="6" placeholder="Để trống nếu không đổi"><label>Ảnh hiện tại</label><img class="thumb large" src="../uploads/<?=e($u['images']?:'default.svg')?>" alt="Ảnh"><label>Chọn ảnh mới</label><input type="file" name="image" accept="image/*"><div class="actions"><button class="primary">Cập nhật</button><a class="button" href="index.php">Hủy</a></div></form></section></main></body></html>
